/// ===========================================================================
/// Collision events
///
/// Drained by the game, not pushed to it. The engine resolves the geometry
/// generically; game-specific response (spin, speed-up, scoring, audio) reads
/// these events and reacts. There is no ResolvePaddleBounce().
/// ==========================================================================
final class EshiCollisionEvent extends ffi.Struct {
  @EshiEntity()
  external int a;

  @EshiEntity()
  external int b;

  /// < Contact normal, pointing from b toward a.
  @ffi.Float()
  external double nx;

  @ffi.Float()
  external double ny;

  @ffi.Float()
  external double penetration;

  static ffi.Pointer<EshiCollisionEvent> $allocate(
    ffi.Allocator $allocator, {
    required int a,
    required int b,
    required double nx,
    required double ny,
    required double penetration,
  }) => $allocator<EshiCollisionEvent>()
    ..ref.a = a
    ..ref.b = b
    ..ref.nx = nx
    ..ref.ny = ny
    ..ref.penetration = penetration;
}

/// ===========================================================================
/// Command buffer — one boundary crossing per frame
///
/// A dart:ffi leaf call is cheap but not free, and thousands of them per frame
/// plus the attendant GC pressure is exactly the overhead the data-oriented
/// layout exists to remove. So the boundary is crossed in bulk: the world owns
/// one buffer of 32-bit words, the caller maps it once — Dart wraps the same
/// bytes in an Int32List and a Float32List through asTypedList — writes packed
/// commands into it, and calls eshi_commands_flush() once. Events travel the
/// same way in reverse. Bulk in, bulk out.
///
/// Wire format. Every command is one header word followed by its payload:
///
/// [ opcode:16 | payload_words:16 ][ payload_0 ] ... [ payload_n-1 ]
///
/// The length in the header is what lets the decoder bounds-check a buffer
/// written by another language, and what lets a newer writer append payload
/// words an older reader ignores. It is deliberately *not* a licence to skip
/// unknown opcodes: an opcode this core does not implement stops the flush with
/// ESHI_ERR_UNSUPPORTED, because a Dart package that silently drops half a
/// scene is worse than one that refuses to run against a mismatched core.
///
/// Float payloads are IEEE-754 bit patterns carried in a word.
/// ==========================================================================
enum EshiCommand {
  /// < No payload. Padding.
  ESHI_CMD_NOP(0),

  /// < u32 epoch. Opens a reconcile pass.
  ESHI_CMD_SCENE_BEGIN(1),

  /// < u32 key, non-zero. Selects/creates a node.
  ESHI_CMD_NODE(2),

  /// < f32 x, f32 y.
  ESHI_CMD_TRANSFORM(3),

  /// < f32 vx, f32 vy.
  ESHI_CMD_VELOCITY(4),

  /// < f32 hx, hy; u32 layer, mask, flags.
  ESHI_CMD_COLLIDER(5),

  /// < f32 restitution.
  ESHI_CMD_RESTITUTION(6),

  /// < f32 min_x, max_x, min_y, max_y.
  ESHI_CMD_BOUNDS(7),

  /// < No payload. Runs the sweep.
  ESHI_CMD_SCENE_END(8),

  /// < u32 EshiKey, u32 down.
  ESHI_CMD_INPUT(9);

  final int value;
  const EshiCommand(this.value);

  static EshiCommand fromValue(int value) => switch (value) {
    0 => ESHI_CMD_NOP,
    1 => ESHI_CMD_SCENE_BEGIN,
    2 => ESHI_CMD_NODE,
    3 => ESHI_CMD_TRANSFORM,
    4 => ESHI_CMD_VELOCITY,
    5 => ESHI_CMD_COLLIDER,
    6 => ESHI_CMD_RESTITUTION,
    7 => ESHI_CMD_BOUNDS,
    8 => ESHI_CMD_SCENE_END,
    9 => ESHI_CMD_INPUT,
    _ => throw ArgumentError('Unknown value for EshiCommand: $value'),
  };
}

final class EshiConfig extends ffi.Struct {
  /// < Framebuffer width in pixels.
  @ffi.Int32()
  external int width;

  /// < Framebuffer height in pixels.
  @ffi.Int32()
  external int height;

  /// < Requested backend tier.
  @ffi.UnsignedInt()
  external int gradeAsInt;

  EshiGrade get grade => EshiGrade.fromValue(gradeAsInt);
  set grade(EshiGrade value) => gradeAsInt = value.value;

  /// < Simulation step. 0 selects 1/60.
  @ffi.Float()
  external double fixed_dt;

  /// < RNG seed. Equal seeds produce equal frames.
  @ffi.Uint64()
  external int seed;

  /// < 0 selects 4096.
  @ffi.Uint32()
  external int max_entities;

  static ffi.Pointer<EshiConfig> $allocate(
    ffi.Allocator $allocator, {
    required int width,
    required int height,
    required EshiGrade grade,
    required double fixed_dt,
    required int seed,
    required int max_entities,
  }) => $allocator<EshiConfig>()
    ..ref.width = width
    ..ref.height = height
    ..ref.grade = grade
    ..ref.fixed_dt = fixed_dt
    ..ref.seed = seed
    ..ref.max_entities = max_entities;
}

/// ===========================================================================
/// Entities
///
/// 32-bit storage: 17-bit index + 8-bit generation. The generation makes a stale
/// handle detectable rather than silently aliasing a recycled slot. Width and
/// bit layout match Filament's utils::Entity in the vendored release so the
/// render bridge can adopt it as the shared id without a translation table.
/// ==========================================================================
typedef EshiEntity = ffi.Uint32;
typedef DartEshiEntity = int;

/// ===========================================================================
/// Event buffer — the same trick in reverse
///
/// Same framing as commands, so one codec serves both directions.
/// ==========================================================================
enum EshiEventType {
  /// < u32 a, u32 b; f32 nx, ny, penetration.
  ESHI_EVENT_COLLISION(1);

  final int value;
  const EshiEventType(this.value);

  static EshiEventType fromValue(int value) => switch (value) {
    1 => ESHI_EVENT_COLLISION,
    _ => throw ArgumentError('Unknown value for EshiEventType: $value'),
  };
}

/// Supplies OpenGL entry points for the Paper backend.
///
/// The core links no windowing library, so it cannot resolve GL symbols itself.
/// The host — which already owns the context — passes its loader (SDL_GL_GetProcAddress
/// or equivalent) and guarantees a current context on every eshi_render() call.
/// This is the boundary rule from ARCHITECTURE.md §5 applied to OpenGL.
typedef EshiGlProcLoader =
    ffi.Pointer<ffi.NativeFunction<EshiGlProcLoaderFunction>>;
typedef EshiGlProcLoaderFunction =
    ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Char> name);

/// ===========================================================================
/// Kantei (判定) — hardware capability grades.
///
/// The grade selects a render backend. Ink is below Filament's hardware floor
/// and remains reachable on CPU-only targets. Paper uses the lightweight GL
/// backend. Brush uses direct Metal by default and Filament when that optional
/// integration is built. Gold remains reserved for specialized hardware.
/// ==========================================================================
enum EshiGrade {
  /// < Pure CPU / software raster. ESP32, Playdate, server.
  ESHI_GRADE_INK(1),

  /// < GLES 2.0 / WebGL1 class hardware.
  ESHI_GRADE_PAPER(2),

  /// < Metal / Vulkan / DX12 class hardware.
  ESHI_GRADE_BRUSH(3),

  /// < Ray tracing cores, neural accelerators.
  ESHI_GRADE_GOLD(4);

  final int value;
  const EshiGrade(this.value);

  static EshiGrade fromValue(int value) => switch (value) {
    1 => ESHI_GRADE_INK,
    2 => ESHI_GRADE_PAPER,
    3 => ESHI_GRADE_BRUSH,
    4 => ESHI_GRADE_GOLD,
    _ => throw ArgumentError('Unknown value for EshiGrade: $value'),
  };
}

/// ===========================================================================
/// Input — abstract keys only.
///
/// The core has no idea SDL exists. Hosts translate their native scancodes to
/// these and push them in before eshi_tick(). This is what lets one game source
/// run unmodified under both the SDL host and the Flutter embedder.
/// ==========================================================================
enum EshiKey {
  ESHI_KEY_UP(0),
  ESHI_KEY_DOWN(1),
  ESHI_KEY_LEFT(2),
  ESHI_KEY_RIGHT(3),
  ESHI_KEY_W(4),
  ESHI_KEY_A(5),
  ESHI_KEY_S(6),
  ESHI_KEY_D(7),
  ESHI_KEY_SPACE(8),
  ESHI_KEY_ESCAPE(9),
  ESHI_KEY_COUNT(10);

  final int value;
  const EshiKey(this.value);

  static EshiKey fromValue(int value) => switch (value) {
    0 => ESHI_KEY_UP,
    1 => ESHI_KEY_DOWN,
    2 => ESHI_KEY_LEFT,
    3 => ESHI_KEY_RIGHT,
    4 => ESHI_KEY_W,
    5 => ESHI_KEY_A,
    6 => ESHI_KEY_S,
    7 => ESHI_KEY_D,
    8 => ESHI_KEY_SPACE,
    9 => ESHI_KEY_ESCAPE,
    10 => ESHI_KEY_COUNT,
    _ => throw ArgumentError('Unknown value for EshiKey: $value'),
  };
}

/// A material, described once for every tier.
///
/// Ink executes `cpu_shader` directly — it is compiled into the binary. The GPU
/// tiers cannot call a host function pointer. Lightweight GPU backends take
/// `source_path` and transpile it at runtime; packaged renderers take a material
/// package produced by the offline toolchain. Supplying all representations is
/// what lets one material run on every grade; omitting one restricts it to the
/// remaining tiers.
///
/// Source-backed tiers get shader hot-reload by rebinding after a file change.
/// Package-backed tiers rebind a rebuilt package; Ink remains compiled into the
/// host binary. The representation changes, but the material API does not.
final class EshiMaterial extends ffi.Struct {
  /// < Ink. NULL restricts the material to GPU tiers.
  external EshiShaderFn cpu_shader;

  /// < Runtime-transpiled source, or NULL.
  external ffi.Pointer<ffi.Char> source_path;

  /// < Offline-compiled material package, or NULL.
  external ffi.Pointer<ffi.Char> package_path;

  /// < Caller-owned block, or NULL.
  external ffi.Pointer<ffi.Void> uniform_data;

  /// < Bytes of `uniform_data`.
  @ffi.Size()
  external int uniform_size;

  static ffi.Pointer<EshiMaterial> $allocate(
    ffi.Allocator $allocator, {
    required EshiShaderFn cpu_shader,
    required ffi.Pointer<ffi.Char> source_path,
    required ffi.Pointer<ffi.Char> package_path,
    required ffi.Pointer<ffi.Void> uniform_data,
    required int uniform_size,
  }) => $allocator<EshiMaterial>()
    ..ref.cpu_shader = cpu_shader
    ..ref.source_path = source_path
    ..ref.package_path = package_path
    ..ref.uniform_data = uniform_data
    ..ref.uniform_size = uniform_size;
}

enum EshiResult {
  ESHI_OK(0),

  /// < Bad argument or dead entity.
  ESHI_ERR_INVALID(-1),

  /// < Grade or feature not built in this binary.
  ESHI_ERR_UNSUPPORTED(-2),
  ESHI_ERR_NOMEM(-3),

  /// < A fixed capacity was exhausted.
  ESHI_ERR_LIMIT(-4),

  /// < A scene older than the world's epoch; ignored.
  ESHI_ERR_STALE(-5),

  /// < ABI or packed-protocol versions are incompatible.
  ESHI_ERR_VERSION(-6);

  final int value;
  const EshiResult(this.value);

  static EshiResult fromValue(int value) => switch (value) {
    0 => ESHI_OK,
    -1 => ESHI_ERR_INVALID,
    -2 => ESHI_ERR_UNSUPPORTED,
    -3 => ESHI_ERR_NOMEM,
    -4 => ESHI_ERR_LIMIT,
    -5 => ESHI_ERR_STALE,
    -6 => ESHI_ERR_VERSION,
    _ => throw ArgumentError('Unknown value for EshiResult: $value'),
  };
}

/// Fragment entry point.
///
/// @param out_rgba   Four floats, unclamped linear RGBA, written by the shader.
/// @param frag_x     Pixel centre, origin bottom-left, matching Shadertoy.
/// @param frag_y
/// @param res_x      Framebuffer resolution.
/// @param res_y
/// @param time       Seconds. Derived from the frame index in headless renders.
/// @param uniforms   The game's block, or NULL if none was set.
typedef EshiShaderFn = ffi.Pointer<ffi.NativeFunction<EshiShaderFnFunction>>;
typedef EshiShaderFnFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Float> out_rgba,
      ffi.Float frag_x,
      ffi.Float frag_y,
      ffi.Float res_x,
      ffi.Float res_y,
      ffi.Float time,
      ffi.Pointer<ffi.Void> uniforms,
    );
typedef DartEshiShaderFnFunction =
    void Function(
      ffi.Pointer<ffi.Float> out_rgba,
      double frag_x,
      double frag_y,
      double res_x,
      double res_y,
      double time,
      ffi.Pointer<ffi.Void> uniforms,
    );

/// ===========================================================================
/// Systems — pure functions over component arrays.
///
/// Systems run in ascending `order`, and ties break on registration sequence.
/// The ordering is stable across runs, which is one of the three things the
/// deterministic video export depends on (the others being the fixed timestep
/// and the seeded RNG).
/// ==========================================================================
typedef EshiSystemFn = ffi.Pointer<ffi.NativeFunction<EshiSystemFnFunction>>;
typedef EshiSystemFnFunction =
    ffi.Void Function(
      ffi.Pointer<EshiWorld> w,
      ffi.Float dt,
      ffi.Pointer<ffi.Void> user,
    );
typedef DartEshiSystemFnFunction =
    void Function(
      ffi.Pointer<EshiWorld> w,
      double dt,
      ffi.Pointer<ffi.Void> user,
    );

/// ===========================================================================
/// Structure-of-arrays views
///
/// Views are borrowed pointers into dense component storage, valid until the
