    required ffi.Pointer<ffi.Float> y,
    required int count,
  }) => $allocator<EshiTransformView>()
    ..ref.entity = entity
    ..ref.x = x
    ..ref.y = y
    ..ref.count = count;
}

final class EshiVelocityView extends ffi.Struct {
  external ffi.Pointer<EshiEntity> entity;

